using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;
using SpawnDev.ILGPU.ML.Preprocessing;

namespace SpawnDev.ILGPU.ML.Assets;

/// <summary>
/// The OpenAI Images API (DALL-E 3, or gpt-image-1) as a picture source for <see cref="AssetGenerator"/>, next to the local FLUX.2 klein and SD-Turbo.
/// TRELLIS (whose project page shows its image prompts generated by DALL-E 3) takes any picture, so any image generator can feed it.
/// <para>
/// <b>Opt in.</b> Unlike every other stage of this library, this one is not local: the prompt is sent to api.openai.com with your API key, and OpenAI bills the request. Nothing here
/// reads a key from the environment, stores one or logs one; the application passes it in (the console example reads <c>OPENAI_API_KEY</c> only when <c>--image-model openai</c> is asked for).
/// DALL-E 3 makes one picture per request (no seed), so N pictures are N requests.
/// </para>
/// </summary>
public sealed class OpenAiImageSource : IDisposable
{
    public const string DefaultEndpoint = "https://api.openai.com/v1/images/generations";

    private readonly string _apiKey, _model, _size, _endpoint;
    private readonly HttpClient _http;
    private readonly bool _ownsHttp;

    /// <param name="apiKey">your OpenAI API key; sent only as the bearer token of the request</param>
    /// <param name="model">"dall-e-3" (default) or "gpt-image-1"</param>
    /// <param name="size">"1024x1024" (default; DALL-E 3 also 1792x1024 and 1024x1792)</param>
    /// <param name="http">a client to use (tests, proxies); null makes one</param>
    /// <param name="endpoint">override the endpoint (a proxy, a compatible server)</param>
    public OpenAiImageSource(string apiKey, string model = "dall-e-3", string size = "1024x1024", HttpClient? http = null, string? endpoint = null)
    {
        if (string.IsNullOrWhiteSpace(apiKey)) throw new ArgumentException("An OpenAI API key is required.", nameof(apiKey));
        _apiKey = apiKey; _model = model; _size = size; _endpoint = endpoint ?? DefaultEndpoint;
        _http = http ?? new HttpClient { Timeout = TimeSpan.FromMinutes(3) };
        _ownsHttp = http == null;
    }

    /// <summary>Draw one picture. <paramref name="index"/> labels it (the 3D stage uses it as its seed); the service has no seed.</summary>
    public async Task<AssetPicture> DrawAsync(string prompt, int index, CancellationToken ct = default)
    {
        using var req = new HttpRequestMessage(HttpMethod.Post, _endpoint);
        req.Headers.Authorization = new AuthenticationHeaderValue("Bearer", _apiKey);
        using var ms = new MemoryStream();
        using (var jw = new Utf8JsonWriter(ms))
        {
            jw.WriteStartObject();
            jw.WriteString("model", _model); jw.WriteString("prompt", prompt); jw.WriteNumber("n", 1); jw.WriteString("size", _size);
            if (_model.StartsWith("dall-e", StringComparison.OrdinalIgnoreCase)) jw.WriteString("response_format", "b64_json");       // gpt-image-1 always answers base64 and rejects the field
            jw.WriteEndObject();
        }
        req.Content = new StringContent(Encoding.UTF8.GetString(ms.ToArray()), Encoding.UTF8, "application/json");
        using var resp = await _http.SendAsync(req, ct);
        var text = await resp.Content.ReadAsStringAsync(ct);
        using var doc = JsonDocument.Parse(text);
        if (!resp.IsSuccessStatusCode)
        {
            string message = doc.RootElement.TryGetProperty("error", out var e) && e.TryGetProperty("message", out var m) ? m.GetString() ?? "" : text;
            throw new HttpRequestException($"OpenAI images request failed ({(int)resp.StatusCode}): {message}");
        }
        var b64 = doc.RootElement.GetProperty("data")[0].GetProperty("b64_json").GetString() ?? throw new InvalidDataException("The response holds no image.");
        var png = Convert.FromBase64String(b64);
        var (w, h) = PngDecoder.GetDimensions(png);
        var rgba = PngDecoder.DecodePixels(png) ?? throw new InvalidDataException("The returned PNG could not be decoded (only 8-bit, non-interlaced PNGs are supported).");
        return new AssetPicture(index, w, h, rgba);
    }

    public void Dispose() { if (_ownsHttp) _http.Dispose(); }
}
